using UnityEngine;
using Framework.Grid;

namespace Game.Tests
{
    /// <summary>
    /// グリッド座標変換機能の動作確認用クラス。
    /// </summary>
    public class GridCoordinateConverterTest : MonoBehaviour
    {
        #region Fields

        [Header("参照設定")]

        /// <summary>テスト対象の座標変換コンポーネント。</summary>
        [SerializeField]
        [Tooltip("テスト対象の座標変換コンポーネント")]
        private GridCoordinateConverter converter;

        [Header("テスト設定")]

        /// <summary>変換テストに使用するグリッド座標。</summary>
        [SerializeField]
        [Tooltip("変換テストに使用するグリッド座標")]
        private Vector2Int testCellPosition =
            new Vector2Int(3, 2);

        /// <summary>変換テストに使用するワールド座標。</summary>
        [SerializeField]
        [Tooltip("変換テストに使用するワールド座標")]
        private Vector3 testWorldPosition =
            new Vector3(3.2f, 2.8f, 0f);

        /// <summary>Sceneビューに表示するマーカーの半径。</summary>
        [SerializeField]
        [Min(0.01f)]
        [Tooltip("Sceneビューに表示するマーカーの半径")]
        private float gizmoRadius = 0.1f;

        #endregion

        #region Unity Methods

        /// <summary>
        /// 座標変換の動作確認を実行する。
        /// </summary>
        private void Start()
        {
            // コンポーネントの設定漏れを確認する。
            if (converter == null)
            {
                Debug.LogError(
                    "座標変換コンポーネントが未設定です。",
                    this);

                return;
            }

            TestCellToWorld();
            TestWorldToCell();
            TestSnap();
        }

        /// <summary>
        /// Sceneビューにテスト座標を可視化する。
        /// </summary>
        private void OnDrawGizmos()
        {
            if (converter == null)
            {
                return;
            }

            // テスト対象のマスの原点座標。
            Vector3 origin =
                converter.CellToWorld(testCellPosition);

            // テスト対象のマスの中心座標。
            Vector3 center =
                converter.GetCellCenterWorld(testCellPosition);

            // ワールド座標を補正した位置。
            Vector3 snappedPosition =
                converter.SnapToCellCenter(testWorldPosition);

            // 赤色：マスの原点。
            Gizmos.color = Color.red;
            Gizmos.DrawSphere(origin, gizmoRadius);

            // 緑色：マスの中心。
            Gizmos.color = Color.green;
            Gizmos.DrawSphere(center, gizmoRadius);

            // 黄色：補正前のワールド座標。
            Gizmos.color = Color.yellow;
            Gizmos.DrawSphere(testWorldPosition, gizmoRadius);

            // 水色：補正前後の座標を結ぶ線。
            Gizmos.color = Color.cyan;
            Gizmos.DrawLine(
                testWorldPosition,
                snappedPosition);
        }

        #endregion

        #region Test Methods

        /// <summary>
        /// グリッド座標からワールド座標への変換を確認する。
        /// </summary>
        private void TestCellToWorld()
        {
            // 指定マスの原点座標。
            Vector3 origin =
                converter.CellToWorld(testCellPosition);

            // 指定マスの中心座標。
            Vector3 center =
                converter.GetCellCenterWorld(testCellPosition);

            Debug.Log(
                $"グリッド座標：{testCellPosition}\n" +
                $"マスの原点：{origin}\n" +
                $"マスの中心：{center}");

            // 中心座標をグリッド座標に戻す。
            Vector2Int restoredPosition =
                converter.WorldToCell2D(center);

            Debug.Assert(
                restoredPosition == testCellPosition,
                "座標の往復変換に失敗しました。");
        }

        /// <summary>
        /// ワールド座標からグリッド座標への変換を確認する。
        /// </summary>
        private void TestWorldToCell()
        {
            // ワールド座標が所属するマス。
            Vector2Int cellPosition =
                converter.WorldToCell2D(testWorldPosition);

            Debug.Log(
                $"ワールド座標：{testWorldPosition}\n" +
                $"変換後のグリッド座標：{cellPosition}");
        }

        /// <summary>
        /// マスの中心座標への補正処理を確認する。
        /// </summary>
        private void TestSnap()
        {
            // マスの中心に補正した座標。
            Vector3 snappedPosition =
                converter.SnapToCellCenter(testWorldPosition);

            Debug.Log(
                $"補正前：{testWorldPosition}\n" +
                $"補正後：{snappedPosition}");
        }

        #endregion
    }
}
